#!/usr/bin/env bash
# clean.sh - removes everything generated by build.sh / verify.sh / sender.sh
# (only build/ and artifacts/, source files are never touched)

. "$(dirname "$0")/common.sh"

GENERATED_DIRS="build $ARTIFACTS_DIR"

for directory in $GENERATED_DIRS; do
    if [ -e "$directory" ]; then
        log_info "removing $directory/"
        rm -rf "$directory" || { log_error "could not remove $directory/"; exit 1; }
    fi
done

log_info "clean done"
exit 0
